import com.luci.pianoroom.*;import java.io.*;import java.nio.*;import java.nio.file.*;import java.util.*;
public final class StudioTest {
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 public static void main(String[] args)throws Exception {
  Scene scene=new Scene();scene.name="Cauda + cordas";scene.banks[2]="import-123.sf2";scene.programs[2]=48;scene.gains[2]=2;scene.muted[1]=true;scene.solo=2;scene.yamaha=true;scene.pianoVolume=0;scene.pianoMode=1;Scene restored=Scene.decode(scene.encode());check(restored.name.equals(scene.name)&&restored.banks[2].equals(scene.banks[2])&&restored.programs[2]==48&&restored.gains[2]==2&&restored.muted[1]&&restored.solo==2&&restored.yamaha&&restored.pianoVolume==0,"full scene round trip");scene.gains[0]=Float.NaN;try{Scene.decode(scene.encode());throw new AssertionError("NaN accepted");}catch(IOException expected){}scene.gains[0]=.8f;scene.banks[0]="../bad.sf2";try{Scene.decode(scene.encode());throw new AssertionError("path accepted");}catch(IOException expected){}
  File midi=File.createTempFile("piano-tape", ".mid");List<MidiTape.Event> events=new ArrayList<>();MidiTape tape=new MidiTape();tape.start();tape.add(0xB5,64,127);tape.add(0x95,60,73);Thread.sleep(35);tape.add(0x85,60,0);tape.stop();tape.save(midi);events=MidiTape.read(midi);check(events.get(0).status==0xB5&&events.get(1).b==73&&events.get(2).micros>=30000,"MIDI note/pedal/velocity/time preserved");check(events.get(events.size()-1).status==0xB5&&events.get(events.size()-1).a==123,"recorded channel all-notes-off");midi.delete();
  check(InstrumentCatalog.name("Violin",0,40,false).equals("Violino")&&InstrumentCatalog.family(128,0)==16&&InstrumentCatalog.art(0,24,false)==23,"localized family catalog");System.out.println("PASS: scenes preserve 4 channels, volumes/mute/solo/Yamaha; invalid settings rejected; MIDI timing, raw velocity, pedal and selected channel preserved; localized catalog.");
  long bank=Synth.load(args[0]);check(bank!=0,"font");Synth synth=new Synth();for(int i=0;i<4;i++){synth.setLayer(i,bank,i==0?0:i==1?4:i==2?48:89);synth.setGain(i,.2f);}if(args.length>1)synth.backend(1);synth.start();Thread.sleep(180);WavRecorder recorder=new WavRecorder();File wave=File.createTempFile("piano-wave", ".wav");recorder.start(wave,synth.sampleRate());synth.midi(0xB0,64,127);for(int i=0;i<16;i++){synth.midi(0x90,48+i,100);synth.midi(0x80,48+i,0);Thread.sleep(12);}Thread.sleep(200);recorder.finish();check(recorder.error.isEmpty()&&recorder.bytes>4096&&recorder.firstNanos>0,"worker records real native mixed PCM");byte[] bytes=Files.readAllBytes(wave.toPath());ByteBuffer header=ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN);check(header.getInt(40)==bytes.length-44&&header.getInt(24)==synth.sampleRate(),"WAV header and length");boolean sound=false;for(int i=44;i<bytes.length;i++)sound|=bytes[i]!=0;check(sound,"WAV is audible, all four sampler channels");int[] voices=synth.voicesNow();check(voices[0]>0&&voices[1]>0&&voices[2]>0&&voices[3]>0,"4 simultaneous channels");synth.quality(512);synth.midi(0x90,75,100);Thread.sleep(30);check(synth.voicesNow()[0]>0,"quality change keeps channel preset");synth.close();Synth.freeBank(bank);wave.delete();System.out.println("PASS: 4-channel actual JNI mixer records stereo WAV via native SPSC tap and disk worker; quality change preserves playable channels. Host simulated audio route.");
 }
}
